//! Closed BQ050/BQ051 command programs, pinned to the tracked original images.
use crate::{catalog,engine::RuleResult,model::*,rules::*};
pub(crate) const IDS:[&str;2]=["BQ050","BQ051"];
fn same<T:serde::Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
fn damage()->TargetSlotSpec{target(Zone::Board,EntityKind::Character,Relation::Any,Range::Anywhere)}
fn attachment()->TargetSlotSpec{let mut t=target(Zone::Board,EntityKind::Attachment,Relation::Any,Range::Anywhere);t.predicate=Some(TargetPredicate::BQ050EnemySocietyAttachment);t}
pub(crate) fn definition(id:&str)->Definition{
 let mut a=ability(if id=="BQ050"{"bq050-command"}else{"bq051-command"},if id=="BQ050"{"破坏欲：选择一项或两项"}else{"大暴走：核心及触手所在地清场"},Timing::Standard,vec![],vec![],vec![],None);a.play_only=true;
 if id=="BQ050"{a.modes=vec![Mode{key:"damage".into(),label:"对目标角色造成1伤害".into(),targets:vec![damage()],ops:vec![Op::DamageTarget{slot:0,amount:1}]},Mode{key:"attachment".into(),label:"消灭敌方秘社上的目标附属".into(),targets:vec![attachment()],ops:vec![Op::Destroy(EntityRef::Target(0))]},Mode{key:"both".into(),label:"伤害角色并消灭秘社附属".into(),targets:vec![damage(),attachment()],ops:vec![Op::DamageTarget{slot:0,amount:1},Op::Destroy(EntityRef::Target(1))]}];}else{a.ops=vec![Op::BQ051Sweep];}with_abilities(vec![a])
}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("bq050-")||a.key.starts_with("bq051-")||a.ops.iter().any(|o|matches!(o,Op::BQ051Sweep))||a.targets.iter().chain(a.modes.iter().flat_map(|m|&m.targets)).any(|t|t.predicate==Some(TargetPredicate::BQ050EnemySocietyAttachment))}
fn selected(id:&str)->Vec<AbilitySpec>{let a=definition(id).abilities.remove(0);let mut out=vec![a.clone()];for m in &a.modes{let mut b=a.clone();b.targets=m.targets.clone();b.ops=m.ops.clone();b.modes.clear();out.push(b);}out}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{if !IDS.contains(&id)||!selected(id).iter().any(|b|same(a,b)){return Err("修格斯命令须保留完整模式、目标和程序".into());}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if (IDS.contains(&id)||d.abilities.iter().any(related))&&(!IDS.contains(&id)||!same(d,&definition(id))){return Err("修格斯命令定义不可改写或移植".into());}Ok(())}
impl Game{
 pub(crate) fn has_shoggoth(&self,actor:usize)->bool{self.players.get(actor).and_then(|p|p.society_zone.card.as_ref()).is_some_and(|c|c.definition=="MSBQ02"&&!c.face_down&&c.controller==actor)}
 pub(crate) fn bq050_attachment(&self,actor:usize,source:&SourceSnapshot,id:&str)->bool{source.card.definition=="BQ050"&&self.attachments.iter().any(|a|a.card.id==id&&self.attachment_host_valid(a)&&self.society_host_seat(&a.host_id).is_some_and(|s|self.team(s)!=self.team(actor)))}
 pub(crate) fn bq050_reduction(&self,actor:usize,c:&Card)->u32{if c.definition=="BQ050"&&self.selected_core_source(actor).is_ok_and(|s|s.region.is_some()){3}else{0}}
 pub(crate) fn bq_command_action(&self,actor:usize,c:&Card,a:&Action)->RuleResult<()>{if !IDS.contains(&c.definition.as_str()){return Ok(());}if a.kind=="asset"&&c.definition=="BQ051"{return Ok(());}if !self.has_shoggoth(actor){return Err("该牌为修格斯秘社限定".into());}
 let expected=Action{card_id:a.card_id.clone(),ability_id:a.ability_id.clone(),option:if c.definition=="BQ050"{a.option.clone()}else{None},target_id:if c.definition=="BQ050"&&a.option.as_deref()!=Some("both"){a.target_id.clone()}else{None},selected:if c.definition=="BQ050"&&a.option.as_deref()==Some("both"){a.selected.clone()}else{None},..Action::new("play")};if *a!=expected{return Err("修格斯命令载荷与原模式不符".into());}Ok(())}
 pub(crate) fn bq050_bind(&self,actor:usize,source:&SourceSnapshot,spec:&AbilitySpec,a:&Action)->RuleResult<Vec<BoundTarget>>{validate_ability("BQ050",spec)?;let ids=a.selected.as_ref().filter(|v|v.len()==2).ok_or("两项模式须预先声明角色和附属两个目标")?;spec.targets.iter().zip(ids).map(|(slot,id)|{if !self.valid_binding(actor,source,slot,id){return Err("破坏欲目标不合法".into());}Ok(BoundTarget{region_instance:None,id:id.clone(),spec:slot.clone(),public:self.public_target(actor,source,slot,id)})}).collect()}
 pub(crate) fn bq050_candidates(&self,actor:usize,c:&Card)->Vec<(Action,String)>{let source=self.source_snapshot(c,None);let mut out=vec![];for m in definition("BQ050").abilities.remove(0).modes{let first=self.binding_options(actor,&source,&m.targets[0]);for a in first{let seconds=if m.targets.len()==2{self.binding_options(actor,&source,&m.targets[1]).into_iter().map(|b|Some(b.id)).collect()}else{vec![None]};for b in seconds{out.push((Action{card_id:Some(c.id.clone()),ability_id:Some("bq050-command".into()),option:Some(m.key.clone()),target_id:if b.is_none(){Some(a.id.clone())}else{None},selected:b.map(|b|vec![a.id.clone(),b]),..Action::new("play")},format!("破坏欲：{} → {}",m.label,a.label)));}}}out}
 pub(crate) fn validate_bq_command_frame(&self,f:&ResolutionFrame)->RuleResult<()>{let related=IDS.contains(&f.source.card.definition.as_str())||f.ability_key.starts_with("bq050-")||f.ability_key.starts_with("bq051-")||f.steps.iter().any(|s|matches!(s.op,Op::BQ051Sweep))||f.targets.iter().any(|t|t.spec.predicate==Some(TargetPredicate::BQ050EnemySocietyAttachment));if !related{return Ok(());}let c=&f.source.card;
 if !IDS.contains(&c.definition.as_str())||c.face_down||c.controller!=f.actor||c.owner>=self.players.len()||f.actor>=self.players.len()||!self.mystic_instance_valid(&c.id)||!self.mystic_instance_valid(&f.frame_id)||f.source.region.is_some()||f.source.source_region_instance.is_some()||f.source.play_source.is_some()||f.source.attachment_host_instance.is_some()||f.source.death_echo.is_some()||f.source.observed_death.is_some()||f.source.observed_exposure.is_some()||f.source.observed_mobility_grant.is_some()||f.chosen_region.is_some(){return Err("命令原付费来源无效".into());}
 let valid=selected(&c.definition).into_iter().filter(|a|a.modes.is_empty()).any(|a|a.key==f.ability_key&&same(&a.ops,&f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>())&&a.targets.len()==f.targets.len()&&a.targets.iter().zip(&f.targets).all(|(s,t)|same(s,&t.spec)&&self.mystic_instance_valid(&t.id)&&t.public.instance_id==t.id&&t.region_instance.is_none()&&t.public.valid&&t.public.status=="valid"&&t.public.invalid_reason.is_none()));
 if !valid||f.steps.iter().any(|s|s.context!=f.actor)||f.cursor>f.steps.len()||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor>0&&!matches!(f.guard,GuardState::Accepted)||!matches!(f.already_paid.as_slice(),[PaidCost::Assets(ids)]if f.money_units(0)<=catalog::card(&c.definition).cost as usize&&ids.iter().all(|id|self.mystic_instance_valid(id)&&*id!=c.id)&&ids.iter().collect::<std::collections::BTreeSet<_>>().len()==ids.len()){return Err("命令模式、目标、费用或执行位置损坏".into());}self.mobility_immutable_identity(c)
 }
 pub(crate) fn validate_bq_command_play(&self,item:&StackItem)->RuleResult<()>{if IDS.contains(&item.card.as_ref().map_or("",|c|c.definition.as_str()))||item.frame.as_ref().is_some_and(|f|f.ability_key.starts_with("bq050-")||f.ability_key.starts_with("bq051-")){let f=item.frame.as_ref().ok_or("真实命令事务缺帧")?;self.validate_bq_command_frame(f)?;if !IDS.contains(&f.source.card.definition.as_str())||f.cursor!=0||item.id!=f.frame_id||item.controller!=f.actor||item.reveal||item.deploy_region.is_some()||item.target.as_deref()!=f.targets.first().map(|t|t.id.as_str())||item.card.as_ref().is_none_or(|c|!self.pack_a_transaction_matches(f,c)){return Err("命令事务与原付费帧不符".into());}}Ok(())}
 pub(crate) fn validate_bq_commands(&self)->RuleResult<()>{for item in &self.stack{self.validate_bq_command_play(item)?;}for e in &self.effects{if let Effect::Frame{frame}=e{self.validate_bq_command_frame(frame)?;}}if let Some(Pending{resolution:ChoiceResolution::Frame{frame,..},..})=&self.pending{self.validate_bq_command_frame(frame)?;if IDS.contains(&frame.source.card.definition.as_str()){return Err("命令不可移植为待选帧".into());}}Ok(())}
 pub(crate) fn bq051_sweep(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.validate_bq_command_frame(f)?;if f.source.card.definition!="BQ051"||f.cursor!=1{return Err("大暴走须来自原命令程序".into());}
 let regions=(0..self.regions.len()).filter(|&r|self.region_live(r)&&self.region_characters(r).any(|c|!c.face_down&&c.controller==f.actor&&(self.current_subtypes(c).iter().any(|s|s=="触手")||self.core_zones.iter().any(|z|z.owner==f.actor&&z.definition==c.definition&&z.card.is_none()&&c.owner==f.actor)))).collect::<Vec<_>>();
 let mut deaths=vec![];for r in regions{for (_,c) in self.in_play_cards().into_iter().filter(|(region,_)|*region==Some(r)){if (c.face_down&&!crate::batch4_plans::is_plan(c))||(!c.face_down&&!self.core_zones.iter().any(|z|z.owner==c.owner&&z.definition==c.definition&&z.card.is_none())&&catalog::has_kind(catalog::card(&c.definition),"character")){deaths.push((c.id.clone(),RemovalCause::Destroy,self.source_snapshot(c,Some(r))));}}}self.destroy_wave_as(f.actor,deaths);self.players[f.actor].society_zone.loss_control=3;Ok(())}
}
